<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$tasks=$pdo->query('SELECT t.*,m.matter_reference,m.subject FROM tasks t LEFT JOIN matters m ON m.id=t.matter_id ORDER BY CASE t.status WHEN "completed" THEN 1 ELSE 0 END,COALESCE(t.due_date,"9999-12-31"),t.created_at DESC')->fetchAll();$pageTitle='Tasks | AEP';$activeNav='tasks';require __DIR__.'/includes/header.php';?><div class="actions" style="justify-content:space-between"><div><h1>Tasks</h1><p class="muted">Action list across all matters.</p></div><a class="btn" href="task_create.php">Create task</a></div><div class="card" style="margin-top:18px"><?php if(!$tasks):?><div class="empty">Ready to create your first task.<br><br><a class="btn" href="task_create.php">Create task</a></div><?php else:?><table><thead><tr><th>Task</th><th>Matter</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($tasks as $task):?><tr><td><strong><?php echo aep_h($task['title']);?></strong><br><span class="muted"><?php echo aep_h($task['description']);?></span></td><td><?php echo $task['matter_reference']?'<a href="matter_view.php?id='.(int)$task['matter_id'].'">'.aep_h($task['matter_reference']).'</a>':'—';?></td><td><?php echo aep_h($task['due_date']?:'—');?></td><td><span class="badge"><?php echo aep_h($task['status']);?></span></td><td><a class="btn secondary" href="task_view.php?id=<?php echo (int)$task['id'];?>">Open</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
